-- The two checklists published on 2026-11-19: Asking for Help When You Hate To
-- (Asking for Help) and When a Pet Dies (Pet Loss).
-- Generated by `python3 tools/checklists_sql.py asking-for-help-when-you-hate-to
-- when-a-pet-dies`; the repo copy in data/checklists.json is the source.
-- Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('asking-for-help-when-you-hate-to', 'Asking for Help When You Hate To', 'Open this when something has got too big to carry alone and you keep deciding to manage anyway. It breaks the ask into small steps, so reaching out to one person feels like a specific request rather than an admission.', 'Asking for Help', '["Name the one thing you need — A specific ask is far easier to say and to answer than a general one.", "Pick the person nearby, not the ideal one — Someone close who likes you beats the perfect helper you never call.", "Work out how long it would take them — Knowing it is twenty minutes makes the request smaller for both of you.", "Draft the message before you send it — Writing it and sending it are two jobs, and splitting them helps.", "Say what you have already tried — It shows where the real gap is and tells them where to start.", "Give them an easy way to say no — An out makes a yes mean more and keeps the friendship clean.", "Ask early rather than at the edge — Help arrives better before the deadline than during the crisis.", "Thank them in a way they will notice — Being thanked well makes people glad to be asked again."]'::jsonb, 'as needed', array['Boundaries', 'Communication', 'Shame']::text[], 1, '2026-11-19T16:00:00+00:00'::timestamptz),
  ('when-a-pet-dies', 'When a Pet Dies', 'Open this in the first days after a pet dies, when the house is the wrong kind of quiet and you are not sure you are allowed to grieve this much. It gives the loss its proper size and a few gentle things to do.', 'Pet Loss', '["Say out loud that this is a real loss — Naming it stops you arguing with yourself about whether it counts.", "Keep one thing of theirs in sight — A collar or a bowl on the shelf gives the grief somewhere to sit.", "Tell one person who knew the two of you — Being heard by someone who knew them beats general sympathy.", "Expect the routine to be the hardest part — The empty hour at feeding time catches almost everyone.", "Let yourself cry at the walk you skip — Grief for an animal arrives through habits more than thoughts.", "Write down one ordinary memory — The small daily things fade first and are what you will want back.", "Call or text 988 if you stop wanting to be here — Free, confidential help is there at any hour, and reaching for it is a strong move.", "Decide about another pet later, not now — A choice made in the first week is made by the grief, not by you."]'::jsonb, 'as needed', array['Grief', 'Loss', 'Self-Compassion']::text[], 1, '2026-11-19T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
